/**
 * Runs the REAL, unmodified production quality functions
 * (apps/web/src/lib/cv/quality/{blur,lighting}.ts) against the real fixture
 * images generated by generate_quality_fixtures.js, and records the real
 * measured output. No number in the resulting JSON is invented -- this is
 * the actual algorithm running on actual pixel data.
 *
 * detectBlur/analyzeLighting only touch ImageData's {width, height, data}
 * shape (no browser-specific APIs), so we can hand them a plain object with
 * that shape built from a real decoded JPEG via sharp, with no browser/canvas
 * involved.
 *
 * Run: npx tsx research/cv/scripts/benchmark_image_quality.ts
 */
import sharp from "../../../node_modules/sharp";
import path from "path";
import fs from "fs";
import { detectBlur } from "../../../apps/web/src/lib/cv/quality/blur";
import { analyzeLighting } from "../../../apps/web/src/lib/cv/quality/lighting";

const FIXTURES_DIR = path.resolve(__dirname, "../fixtures/quality");
const RESULTS_PATH = path.resolve(__dirname, "../results/image_quality_benchmark.json");

interface ManifestEntry {
  id: string;
  category: string;
  source: string;
  resolution: string;
  width: number;
  height: number;
  generation: string;
}

async function loadAsImageDataShape(filePath: string): Promise<{ width: number; height: number; data: Uint8ClampedArray }> {
  const { data, info } = await sharp(filePath)
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  return { width: info.width, height: info.height, data: new Uint8ClampedArray(data.buffer, data.byteOffset, data.byteLength) };
}

const CATEGORY_DIR: Record<string, string> = {
  sharp: "sharp",
  mild: "mild_blur",
  heavy: "heavy_blur",
  motion_blur: "motion_blur",
  lighting_dark: "lighting",
  lighting_normal: "lighting",
  lighting_dark_synthetic: "lighting",
  lighting_overexposed: "lighting",
};

async function run() {
  const manifest: ManifestEntry[] = JSON.parse(fs.readFileSync(path.join(FIXTURES_DIR, "manifest.json"), "utf-8"));
  const results: any[] = [];

  for (const entry of manifest) {
    const subdir = CATEGORY_DIR[entry.category];
    const filePath = path.join(FIXTURES_DIR, subdir, entry.id);
    const imageData = await loadAsImageDataShape(filePath);

    const t0 = performance.now();
    const blurVariance = detectBlur(imageData as unknown as ImageData);
    const blurMs = performance.now() - t0;

    const lighting = analyzeLighting(imageData as unknown as ImageData);

    results.push({
      ...entry,
      measured_width: imageData.width,
      measured_height: imageData.height,
      blur_variance: blurVariance,
      blur_compute_ms: Math.round(blurMs * 100) / 100,
      brightness: Math.round(lighting.brightness * 100) / 100,
      is_too_dark: lighting.isTooDark,
      is_overexposed: lighting.isOverexposed,
    });
    console.log(`${entry.id.padEnd(40)} blur_variance=${blurVariance.toFixed(2).padStart(10)}  brightness=${lighting.brightness.toFixed(1).padStart(6)}`);
  }

  fs.mkdirSync(path.dirname(RESULTS_PATH), { recursive: true });
  fs.writeFileSync(RESULTS_PATH, JSON.stringify(results, null, 2));
  console.log(`\nWrote ${results.length} measurements -> ${RESULTS_PATH}`);
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});
